package de.schaepi.puls180;
import android.os.Bundle;import android.graphics.Color;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public class PrivacyActivity extends FontActivity {
private int page=0;private TextView heading,body,counter;private Button previous,next;private ScrollView scroll;private float d;
private final String[] titles={"1. Zweck und Ansprechpartner","2. Messwerte auf deinem Handy","3. Health Connect und Bluetooth","4. Handeingabe und Notizen","5. Speichern, Arzt und andere Apps","6. PC-Tagebuch und Sicherungen","7. Testzeit, Freischaltung und Updates","8. Löschen und deine Rechte","9. Medizinischer Hinweis","10. Hobbyprojekt und Unterstützung"};
private final String[] bodies={"Stand: 26.09.2026\n\nPuls 180 dient dem persönlichen Erfassen, Anzeigen und Weitergeben von Blutdruck- und Pulswerten. Beim ersten Öffnen beginnt automatisch eine vierzehntägige Testzeit. Danach ist eine dauerhafte Freischaltung mit einem gerätegebundenen Kaufschlüssel möglich.\n\nVerantwortliche: Kerstin Kubernat\nKontakt: puls180@t-online.de","Die App speichert geladene und direkt empfangene Messwerte, Notizen, ausgeblendete Einträge, Einstellungen, Name, Größe, Gewicht, Testbeginn und Freischaltungsinformationen im privaten App-Speicher deines Handys. Es sind keine Werbe- oder Analysedienste eingebaut.\n\nGesundheitsdaten werden nicht automatisch an einen Anbieter-Cloudserver gesendet.","Nach deiner Freigabe liest die App Blutdruck und Puls aus Health Connect. Für den direkten Empfang eines unterstützten Messgeräts benötigt sie Bluetooth-Berechtigungen. Das gekoppelte Gerät und die Empfangseinstellungen werden lokal gespeichert.\n\nDie Sprachansage verwendet eine installierte deutsche Offline-Stimme. Personen in deiner Nähe können die vorgelesenen Werte hören.","Über das Menü kannst du SYS, DIA und Puls selbst eintragen. Datum und Uhrzeit setzt die App automatisch. Notizen werden lokal zur jeweiligen Messung gespeichert.\n\nFarbpunkte und Gerätemeldungen dienen der Übersicht und sind keine medizinische Diagnose.","PDF-, Excel-, CSV- und Arztbericht-Dateien entstehen nur, wenn du den entsprechenden Knopf auswählst. Du bestimmst den Speicherort oder die empfangende App. Diese andere App kann die Datei nach ihren eigenen Datenschutzregeln verarbeiten.\n\nPuls 180 verschickt deine Messwerte nicht selbstständig an einen Arzt. Exporte enthalten Gesundheitsdaten und sind nicht zusätzlich verschlüsselt.","Das PC-Tagebuch unterstützt vier getrennte Benutzer. Du kannst alle oder ausgewählte Handywerte ausdrücklich als JSON-Datei speichern oder über „PC-Datei senden an …“ an eine gewählte App übergeben. Beim direkten Kopieren der gespeicherten Datei per USB muss das Handy verbunden sein. Am PC importierst du die Datei beim passend benannten Benutzer. Der QR-/WLAN-Abgleich ist derzeit ausgeschaltet. Die Datei enthält Gesundheitsdaten und ist nicht zusätzlich verschlüsselt. Spätere Löschungen auf dem Handy ändern bereits importierte PC-Werte nicht automatisch.\n\nSelbst erstellte Exporte und Backups bleiben an ihrem gewählten Speicherort, bis du sie dort löschst.","Die vierzehntägige Testzeit beginnt beim ersten Öffnen. Der Kaufschlüssel ist an dieses Handy und seinen 48-stelligen Gerätecode gebunden. Nach erfolgreicher Eingabe bleibt die App dauerhaft freigeschaltet. Beim Ende der Testzeit werden gespeicherte Messungen nicht automatisch gelöscht. Test- und Freischaltungsdaten werden lokal gespeichert.\n\nBeim Öffnen lädt die App über eine verschlüsselte Verbindung eine Sperrliste von GitHub. Der Gerätecode bleibt dabei auf dem Handy; übertragen wird kein Gerätecode. Der Vergleich anonymer Prüfcodes geschieht lokal. Nach Rückgabe oder Stornierung kann die Freischaltung gesperrt werden. Ohne Internet erfolgt die Prüfung beim nächsten Öffnen mit Internet.\n\nDer Kaufschlüssel kann nach einer Neuinstallation oder dem Löschen der App-Daten auf demselben Handy erneut verwendet werden, sofern er nicht gesperrt wurde. Bitte den Schlüssel sicher aufbewahren. Bei einem Gerätewechsel oder nach dem Zurücksetzen des Handys kann ein neuer Gerätecode entstehen; dafür ist eine neue kostenpflichtige Freischaltung erforderlich.\n\nDie Updateprüfung fragt den aktuellen Versionsstand bei GitHub ab. Dabei werden keine Messwerte, Notizen oder Profildaten übertragen.","Du kannst Einträge in der App-Liste ausblenden und wiederherstellen. Dadurch werden Originalwerte in Health Connect nicht gelöscht. App-Daten entfernst du über Android oder durch Deinstallation; Dateien und PC-Daten löschst du getrennt an ihrem Speicherort.\n\nDu kannst Berechtigungen jederzeit in Android oder Health Connect widerrufen. Für Fragen zu Daten, die du dem Verantwortlichen selbst übermittelst, nutze die oben genannte Kontaktadresse.","Puls 180 dient als digitales Tagebuch zur persönlichen Protokollierung und Übersicht von Blutdruck- und Pulswerten. Die App selbst misst keinen Blutdruck. Farbmarkierungen, ESH-/ESC-Skalen, Durchschnittswerte, Pulsdruck, mittlerer arterieller Druck und Gerätemeldungen dienen der übersichtlichen Darstellung und stellen keine Diagnose dar. Die App gibt keine Therapie-, Medikamenten- oder Dosierungsempfehlungen und ersetzt keine ärztliche Beratung, Diagnose oder Behandlung. Bei Beschwerden, auffälligen Werten oder gesundheitlichen Fragen wende dich an medizinisches Fachpersonal.","Diese App ist ein privat entwickeltes Hobbyprojekt und nicht meine hauptberufliche Tätigkeit. Unterstützung erfolgt nach verfügbarer Zeit; feste Antwortzeiten können nicht zugesagt werden."};
public void onCreate(Bundle b){super.onCreate(b);d=getResources().getDisplayMetrics().density;LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding((int)(18*d),(int)(42*d),(int)(18*d),(int)(18*d));root.setBackgroundColor(Appearance.background(this));root.addView(label("Datenschutz",27,true,Color.rgb(20,75,135)));TextView subtitle=label("Klar erklärt: Was mit deinen Daten geschieht",15,false,Color.rgb(80,96,115));subtitle.setPadding(0,0,0,(int)(12*d));root.addView(subtitle);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding((int)(18*d),(int)(16*d),(int)(18*d),(int)(12*d));GradientDrawable bg=new GradientDrawable();bg.setColor(Appearance.card(this));bg.setCornerRadius(16*d);bg.setStroke((int)d,Color.rgb(218,228,240));card.setBackground(bg);heading=label("",21,true,Color.rgb(20,60,105));counter=label("",13,false,Color.rgb(70,125,185));card.addView(heading);card.addView(counter);scroll=new ScrollView(this);body=label("",17,false,Appearance.text(this));body.setTextIsSelectable(true);body.setLineSpacing(0,1.15f);body.setPadding(0,(int)(14*d),0,(int)(14*d));scroll.addView(body);card.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.addView(card,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);bar.setPadding(0,(int)(10*d),0,0);previous=button("‹ Zurück",Color.rgb(70,95,125));next=button("Weiter ›",Color.rgb(25,112,220));bar.addView(previous,new LinearLayout.LayoutParams(0,-2,1));bar.addView(next,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);Button close=button("Zurück zu meinen Werten",Color.rgb(35,155,80));close.setOnClickListener(v->finish());root.addView(close);previous.setOnClickListener(v->{if(page>0){page--;render();}});next.setOnClickListener(v->{if(page<titles.length-1){page++;render();}});setContentView(root);render();}
private TextView label(String value,float size,boolean bold,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}
private Button button(String value,int color){Button b=new Button(this);b.setText(value);b.setTextSize(17);b.setTextColor(Color.WHITE);b.setAllCaps(false);GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(12*d);b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x30ffffff),g,null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,(int)(54*d));p.setMargins((int)(4*d),(int)(4*d),(int)(4*d),(int)(4*d));b.setLayoutParams(p);return b;}
private void render(){heading.setText(titles[page]);counter.setText("Seite "+(page+1)+" von "+titles.length);body.setText(bodies[page]);previous.setEnabled(page>0);next.setEnabled(page<titles.length-1);previous.setAlpha(page>0?1f:.4f);next.setAlpha(page<titles.length-1?1f:.4f);scroll.post(()->scroll.scrollTo(0,0));}
}




